      "instructionsEn": "Write 3-4 English sentences contrasting the present simple and present continuous: a fact or habit of yours (**I work** ...), something temporary you are doing these days (**I'm working** ...), and one sentence with a performative verb such as **I promise**, **I suggest** or **I would advise** (for example in a formal email).",
      "ruleSummary": "Advanced contrast of present simple and present continuous. The present simple describes things that are always true or situations that exist now and will go on indefinitely (It takes me five minutes to get to school), and habits or regular events (I leave work at 5.30 most days). The present continuous describes particular actions that have begun but not ended at the time of speaking, even if not happening at that exact moment (The police are talking to a number of people about the robbery), often with at the moment, at present, currently, just, still; repeated actions around the time of speaking (I'm hearing a lot of good reports about your work these days); and situations that are or may be temporary (She's teaching Maths in Bonn vs She teaches Maths in Bonn). For something regularly done at a particular time, the simple means the action starts then (We usually watch the news at 9.00) while the continuous means it is already in progress then (We're usually watching the news at 9.00). Performative verbs that perform the action they describe (admit, refuse, apologise, promise, recommend, suggest, warn, inform, advise) normally take the present simple (I apologise for the delay), and modals can make them more tentative or polite (I would advise you to..., I have to inform you that...). Judge whether each student sentence uses the tense that matches its meaning and is well formed."
