      "ruleSummary": "Advanced uses of present simple vs present continuous. State verbs (agree, believe, belong to, contain, cost, know, like, love, own, prefer, realise, resemble, etc.) usually take the present simple (I really enjoy travelling), but can take the continuous to stress a temporary situation around now (I'm considering taking early retirement; The children are loving having Jean stay with us). With ache, feel, hurt, look (= seem) both forms mean much the same. Have with a non-state meaning (eat, undergo, take, hold) can be continuous (The neighbours are having a party). The present continuous describes changes, developments and trends (The growing number of visitors is damaging the footpaths). In stories, jokes, sports commentaries and instructions the present simple gives the main events and the present continuous the longer background events. The present continuous with always, constantly, continually or forever stresses repetition, often with annoyance (They're constantly having parties). The present simple reports what we have read or heard (This article explains why...), and I gather, I hear, I see, I understand, It says here introduce news (I gather you're worried about the new job). Judge whether each student sentence uses the form that fits its meaning and is well formed."
