              "kind": "text",
              "text": "When we want to indicate that something happened at a specific time in the past, we use the *past simple*. We can either say when it happened, using a time adverb, or assume that the hearer already knows when it happened or can understand this from the context:",
              "vi": "Khi muốn cho biết một việc đã xảy ra vào một thời điểm cụ thể trong quá khứ, ta dùng thì quá khứ đơn. Ta có thể nói rõ thời điểm bằng một trạng từ chỉ thời gian, hoặc coi như người nghe đã biết việc đó xảy ra khi nào hay có thể hiểu được từ ngữ cảnh:"
