      "ruleSummary": "The present perfect (have/has + past participle) is used for a past event when we don't say precisely when it happened (A French yachtsman has broken the record), when it has a connection with or a consequence for the present (I've washed my hands so that I can help you; My ceiling has fallen in), for how long an existing situation has lasted (Prices have fallen sharply over the past six months; I've had the pains for three weeks now), and for actions repeated up to now (They've been to Chile three times). The past simple is used for something that happened at a specific past time, stated with a time adverb or understood from context (Jane left just a few minutes ago), for situations that existed for a period in the past but not now (The Pharaohs ruled Egypt for thousands of years), when we are interested in when a present situation began (I started to get the pains three weeks ago), and for how long something went on if it is no longer going on (I stayed with my grandparents for six months). A correct student sentence must not combine the present perfect with a finished past time expression (not The Earth has been formed about 4,500 million years ago; not In his twenties he has spent), must use the present perfect for situations continuing to now, and must form the past participle and past simple correctly."
