      "ruleSummary": "The present perfect (have/has + past participle) is used for something that happened in a period of time up to the present (Science has made many major advances this century), for reporting recent inventions, discoveries and productions (Two schoolchildren have invented a device), for repeated actions or events that might happen again (Timson has made 13 films; often with so far, up to now), and for states that existed in the past and still exist now (We have belonged to the tennis club since we moved here). The past simple is used for something at a particular, finished past time (Scientists made some fundamental discoveries in the 18th century), for inventions in the more distant past (Chinese craftsmen invented paper), for repeated actions that are finished and won't happen again (Timson made 13 films before she was killed), and for states that no longer exist (I knew him when we were both working in Rome). Sometimes either tense is possible with little difference in meaning (the experiment was, or has been, a success). In news reports an event is typically introduced with the present perfect and the details follow in the past simple (Jim Cooper has died of cancer. He was 68 and lived in Texas). A correct student sentence must not use the present perfect with a finished past time or a clause like 'when the new routes were introduced', must use the present perfect with ever since and with periods continuing to now, and must form both tenses correctly."
