      "instructionsEn": "Write 3-4 English sentences about your own experiences, using the right tense with time adverbs: at least one present perfect sentence with **just**, **already**, **yet**, **ever** or **never**, one past simple sentence with **ago**, **last week** or **yesterday**, and one sentence with a **since**-clause (for example: Since I started university, I have made many new friends).",
      "ruleSummary": "Time adverbs that connect the past to the present (just, lately, already, since, so far, still, up to now, yet) are normally used with the present perfect (She's just gone to sleep; Have you seen Robert lately?). Adverbs for finished periods of time ((a month) ago, at 3 o'clock, last week, on Monday, once, then, yesterday) take the past simple (Marie died in 1964, not Marie has died). Before, for and recently can go with either tense: present perfect when the situation still continues or is connected to now (We've had the dishwasher for three years), past simple when it is over (We had the car for six years). With today, this morning/week/month, the past simple treats the period as finished (I wrote three letters this morning = the morning is over) and the present perfect treats it as still continuing (I've written three letters this morning = it is still morning). In a sentence with since, the since-clause usually has a past simple and the main clause a present perfect (I haven't been able to play tennis since I broke my arm), but both can be present perfect if both situations continue to now (Since I've lived here, I haven't seen my neighbours). Ever and never take the present perfect for the whole period up to now (the best view I have ever seen) and the past simple for a completed past period (When he was young, he never bothered about his appearance). A correct student sentence must match the tense to the adverb in these ways."
