      "ruleSummary": "The past continuous (was/were + -ing) describes a temporary situation in progress at or around a particular past time (At the time of the robbery, they were staying with my parents), while the past simple describes a completed event that interrupted it or happened during it (Erika dropped her bag while she was getting into her car). State verbs are not normally used in the past continuous (This house belonged to the King of Sweden). Two actions over the same period can both be past continuous (Sally was reading while Kevin was washing up) or often past simple; completed events that follow each other are all past simple (She got up when the alarm clock went off). Permanent or long-term past situations take the past simple (When I was a child I played the violin; He worked hard all his life), though a temporary one can also take the past continuous (I was working in a car factory during the summer of 1976). Repeated past actions normally take the past simple (We visited Spain three times last year), but the past continuous is possible to stress a limited, temporary period (When Carlo was in hospital, we were visiting him twice a day) or when the repeated actions are a background to another event (I was playing tennis a lot during the time I started to get chest pains). A correct student sentence must use these tenses for these meanings."
