      "ruleSummary": "The present perfect continuous (have/has been + -ing) describes a situation or activity that started in the past and has been in progress for a period until now, often with since or for (She's been living in New Zealand for over a year now). Without a time expression it refers to a recent activity and focuses on its present results (Look! It's been snowing), and the activity may still be going on or may just have stopped. It is typical with How long...? questions and when saying how long something has been in progress (How long have you been waiting?); a present tense is used instead when duration is not mentioned (I see Tom most weekends vs I've been seeing a lot of Tom since he moved in). It is not used for a period that finished at a point before now, which needs the past continuous, past simple or past perfect continuous (I was reading until midnight last night), and it is generally avoided with state verbs (I always find it difficult, not I have always been finding). A correct student sentence must use have/has been + -ing with correct agreement and express duration up to now or a recent activity with present results."
