      "ruleSummary": "The past perfect (had + past participle) describes a past situation or activity that took place before another past event or before a particular past time (Jo discovered that Leslie had lied to her). The past simple is used for a single past event on its own, and for events told in chronological order; the past perfect is used when the narrative mentions an event out of order, one that happened before the last event talked about (He moved to the US in 1965. He had made his fortune growing sugar cane). The past perfect also expresses what someone wanted, hoped, expected, meant or thought about doing but didn't (I had wanted to visit the gallery, but it was closed). After time expressions such as after, as soon as, before, by the time and when, the first event can be past simple or past perfect (After Ivan (had) finished reading, he put out the light), but when the second event is a result of the first, the past simple is preferred for both (When the teacher came in, the children stood up). With already and just, the past perfect is used (The film had already begun by the time we arrived). A correct student sentence must use had + past participle only for an event that genuinely happened before another past point, and the past simple for the main sequence of events; check that the order of events is logically clear."
