      "instructionsEn": "Write 3-4 English sentences about a moment in the past (for example, when you got home or when you received some important news). Use the past perfect continuous (**had been + -ing**) for something that had been going on up to that moment, and the past perfect (**had + past participle**) for something that was completed or had happened a number of times. You can try writing a pair of sentences that shows the difference between the two tenses.",
      "ruleSummary": "The past perfect continuous (had been + -ing) describes a situation or activity that went on over a period up to a particular past time, or until shortly before it (She had been wearing high-heeled shoes, and her feet hurt). It focuses on the continuity or duration of the activity, while the past perfect (had + past participle) focuses on its completion or its effects (Bill had been saving since Christmas / Bill had saved enough money to buy the bike). Sometimes the difference is only one of emphasis (I'd been working hard, so I deserved a holiday / I'd worked hard, and the report was finished). To say how long something went on up to a past time, the past perfect continuous is preferred (They had been travelling for about 36 hours); to say how many times something happened, the past perfect is used (I'd heard the symphony many times before, not I'd been hearing). State verbs such as believe, know and own take the past perfect even for duration (I had known Megan since school, not I had been knowing). The past perfect continuous shows an activity had stopped by the past moment (When we met them, they had been riding), whereas the past continuous shows it was still in progress (they were riding). A correct student sentence must form the tense correctly with had been + -ing or had + past participle, choose continuous for duration of an activity and simple for completion, repetition counts or state verbs, and relate the action clearly to a later past time."
