      "ruleSummary": "Will + infinitive and going to + infinitive both talk about the future, often with little difference (John'll / John's going to meet us at 8); going to is preferred in speech and will in formal writing. Going to is used for predictions based on present evidence or on what we have been told (She thinks she's going to faint), while will is used for predictions based on opinion or past experience (The children will enjoy seeing you). For intentions or decisions made before the moment of speaking, going to (or the present continuous) is preferred (Jo's going to do it), but will is used for formal, previously detailed arrangements (The meeting will begin at 10.00) and for decisions made at the moment of speaking (Don't worry. I'll get it). In the main clause of an if-sentence, will or going to are both possible when something is conditional on something else (If we go on like this, we'll / we're going to lose all our money), but only will (or another auxiliary) when one event simply follows another (If you look carefully, you'll find writing on the glass). Shall/shan't can replace will/won't with I and we (When I retire, I shall have more time), but not with other subjects. A correct student sentence must choose going to or will according to evidence vs opinion, prior intention vs spontaneous decision, and use shall only with I or we."
