      "ruleSummary": "The present continuous and going to + infinitive are both used for future activities that are intended or already arranged (She's making a speech next week; We're going to do some climbing); will is not used for arrangements and intentions. Going to is preferred for an intention with no definite arrangement yet (Before I go to China, I'm going to learn some Cantonese), and the present continuous is preferred to emphasise a definite arrangement (They're leaving from Frankfurt at 6.30 pm). The present continuous is not used for predictions about events we cannot control (I think it's going to rain, not it's raining soon), for permanent future situations (People will live / are going to live longer, not are living), or with the verb be (I'm going to be in Tokyo, not I'm being). Going to + go is usually avoided in favour of the present continuous of go (I'm going to town on Saturday). A correct student sentence must use the present continuous only for arranged, controllable events, going to for intentions and evidence-based predictions, and must not use the present continuous for predictions, permanent situations or be."
