      "instructionsEn": "Write 3-4 English sentences about an upcoming trip or event: one about an official timetable (present simple, e.g. **The train leaves at...**), one with a time or conditional clause (**when/after/until/if/in case** + present simple, with **will** in the main clause), and one with a that-/wh-clause about the future (e.g. **I'll let you know when...**).",
      "ruleSummary": "The present simple is used for future events that are part of an official arrangement such as a timetable or programme (Their plane arrives at 2 o'clock; The next meeting is on November 5th); will is also possible with little difference, but the present simple suggests the arrangement is fixed. The present simple is not used for personal plans or predictions, which need will, going to or the present continuous (I'm just staying in tonight, not I just stay in), except for definite predictions based on a timetable (The sun rises at 5.16 tomorrow). In adverbial clauses after time conjunctions (after, before, when, until) and in conditional clauses (if, unless, in case, provided) the present simple, not will, refers to the future (Wait here until I call you; I'll bring a compass in case we get lost). In that- and wh-clauses the present simple is used when both clauses refer to the future (I'll let you know when she gets here, not when she will get here), but when the main clause refers to the present, will is normal in the that-/wh-clause (I guarantee that you'll enjoy the play), with the present simple also possible for fixed arrangements. A correct student sentence must avoid will inside time and conditional clauses, use the present simple for timetabled events, and use will or going to for personal predictions."
