      "instructionsEn": "Look in your diary and write 3-4 English sentences about your definite future plans, using the future continuous (**I'll be + -ing**) or the present continuous (e.g. **I'll be going to university in September.**, **I'm leaving for Prague on the 25th.**). Add one polite question about someone else's plans with **Will you be -ing...?**",
      "ruleSummary": "The future continuous (will be + -ing) describes an activity or event in progress at a particular time or over a particular period in the future, usually with the future time mentioned (Next Friday, the President will be celebrating ten years in power). It is also used for future activities that result from a previous decision or arrangement, or from a routine (He will be taking up his place at university in July; I'll be seeing Tony on Tuesday, that's when we usually meet). For planned future events, the future continuous and the present continuous are often both possible (We will be leaving / are leaving for Istanbul at 7.00), but the present continuous is preferred for surprising or unexpected events (Dr Radford is leaving!). Will, not the future continuous, is used for decisions, willingness, invitations and promises (Ann will help us = she is willing; Ann will be helping us = previously arranged). The future continuous (or going to be + -ing) makes questions about people's plans particularly polite (Will you be starting work on the room today?). A correct student sentence must use will be + -ing for arranged, routine or in-progress future activities, will for willingness or spontaneous decisions, and should use Will you be -ing...? when asking politely about plans."
