      "ruleSummary": "Be to + infinitive is used for formal or official arrangements, formal instructions and orders, and is common in news reports about future events (Work is to begin this week; The medicine is to be taken after meals; You are not to leave the school without my permission). It is only used for things people can control (not The meteorite is to land; use is going to or will). In if-clauses, be to + infinitive says something must happen first (in the main clause) before something else can happen (If humans are to survive, we must address environmental issues now), in contrast to the present simple for a simple future condition (He will retire if he wins gold). The future perfect (will have + past participle) says something will be completed or achieved by a particular future point (By the time you get home I will have cleaned the house); other modals (may, should) can replace will for less certainty. The future perfect continuous (will have been + -ing) emphasises how long something has been going on by a future point, usually with both the point in time and the period (On Saturday we will have been living here for a year); it is not normally used with state verbs (I will have known Derek for 20 years, not will have been knowing). Judge whether each student sentence uses these forms correctly and appropriately."
