      "instructions": "Hãy viết 3-4 câu tiếng Anh về những dự định trong quá khứ. Dùng **I was going to ..., but ...** để đưa ra hai lời bào chữa (ví dụ I was going to tidy up my room, but ...), một câu với **would** hoặc **was about to** nhìn tương lai từ quá khứ, và một câu với **was to have + quá khứ phân từ** cho một việc đã được sắp xếp nhưng không xảy ra.",
      "instructionsEn": "Write 3-4 English sentences about plans in the past. Use **I was going to ..., but ...** to make two excuses (e.g. I was going to tidy up my room, but ...), write one sentence with **would** or **was about to** looking at the future from the past, and one with **was to have + past participle** for something that was arranged but did not happen.",
      "ruleSummary": "To talk about something that was in the future at a particular point in the past, we use the past forms of the usual future forms: will becomes would (we hoped the new one would arrive soon), is going to becomes was going to (I decided I was going to grow tomatoes), is leaving becomes was leaving (I left early because I was collecting my mother at 3.30), will be -ing becomes would be -ing, will have done becomes would have done, is to becomes was to (I heard there was to be an election), is about to becomes was about to (The performance was about to begin when someone started screaming). The context often shows whether the event happened (I was seeing Jim later, but I had to cancel = it did not happen). Was/were to + infinitive describes something that did actually happen later (He was to find out years later that the car was stolen), while was/were to have + past participle describes something that had been arranged but did not happen (I was to have helped with the performance, but I got flu). Excuses are often made with I was going to..., but... . In a present-time frame the ordinary future forms are needed (I hope the work will have finished by the time we get there, not would have). Judge whether each student sentence uses these forms correctly."
