              "text": "We can use **had better** instead of should / ought to, especially in spoken English, to say that we think it would be sensible or advisable to do something. However, we don't use it to talk about the past or to make general comments:",
              "vi": "Chúng ta có thể dùng **had better** thay cho should / ought to, nhất là trong văn nói, để nói rằng mình nghĩ làm việc gì đó là hợp lý hoặc nên làm. Tuy nhiên, chúng ta không dùng nó để nói về quá khứ hay để đưa ra nhận xét chung:"
