      "ruleSummary": "Should and ought to are usually interchangeable for obligation (advice, recommendations, responsibility or duty: You should / ought to send it back) and probability (There should / ought to be some in the drawer). Should is preferred for what an outside authority recommends (The computer should be disconnected from the mains), and only should or would, not ought to, is used for advice with I (I should leave early, if I were you). Should / ought to have + past participle expresses a past obligation not fulfilled, often with criticism or regret (He should have asked me), or an expectation that something has happened or will have happened (He should have arrived by now). Had better can replace should for sensible advice in a particular situation, especially in speech (you'd better ask Ann), but not for the past or for general comments (not You had better have caught..., not parents had better give...), and it takes a bare infinitive (you'd better not go, not not to go). For logical conclusions, must is used, not should or ought to (She must really enjoy it). (Be) supposed to expresses a weaker obligation (I'm supposed to be there at 10.00) and reports what many people think is true (Eating sweets is supposed to be bad for your teeth). Judge whether each student sentence chooses and forms these modals correctly."
