      "ruleSummary": "Will (present) and would (past) describe characteristic behaviour, habits, or things that are or were always true (Every day Dan will come home and turn on the TV; Early planes wouldn't hold more than 30 passengers). Would is not used this way for a single particular past occasion (Last night I gave him a problem and he solved it, not he would solve it). Stressed will/would criticises someone's habits (She will leave all the lights on), and stressed would can refer to a single past occasion that was typical of the person (Well she would say that). For repeated past actions that no longer happen, use would or used to + infinitive (We would / used to lend him money); used to is more informal. Only used to (not would) is used for past states that have changed (The factory used to be in the city centre). Would needs a specific time or set of occasions to be mentioned (Whenever we went to Uncle Frank's, we would play in the garden). Neither is used to say exactly how many times, how long, or at a particular time (We visited Switzerland four times). Questions and negatives: Did you use to...?, I didn't use to...; formal There used not to be...; tags use didn't he?, not usedn't he? Judge whether each student sentence chooses will, would, used to or the past simple correctly and is well formed."
