      "instructions": "Hãy đọc các mẩu tin sau và viết 3-4 câu tiếng Anh phỏng đoán điều có thể xảy ra trong tương lai, dùng **could/may/might** + **well/conceivably/possibly**: núi lửa Mt St Helens ở Mỹ đang hoạt động mạnh hơn; vận động viên Marcel lần trước chỉ trượt kỷ lục thế giới 1.500 mét một phần mười giây và tối nay thi đấu ở Thụy Sĩ; vị Tổng thống 78 tuổi đã ốm một thời gian; một cơn bão đang tiến vào Mexico; các nhà khoa học vừa chế tạo nhiên liệu ô tô từ đậu nành có thể một ngày nào đó thay thế xăng.",
      "instructionsEn": "Read these news items and write 3-4 English sentences speculating on what may happen in the future, using **could/may/might** + **well/conceivably/possibly**: Mt St Helens in the United States is showing increased volcanic activity; in his last race Marcel missed the world 1,500 metres record by only a tenth of a second, and tonight he competes in Switzerland; the President, now 78, has been unwell for some time; a hurricane is approaching Mexico; scientists have developed a soya-based fuel for cars which may one day replace petrol.",
      "ruleSummary": "Possibility with may, might, can and could. In affirmative sentences may or might say something is possibly happening or true (This may/might be his last major speech); might can suggest less possibility. Could (not can) has a similar meaning and is preferred for an unsure opinion (It could be because his mother is ill again). Can is used in affirmatives only for general, theoretical possibility (The temperature can reach 35 degrees in July; Mountain daisies can be yellow or red), not a particular situation (It may/might/could rain later, not It can rain later). May is preferred in formal contexts (Exceeding the stated dose may cause drowsiness). May is not used to ask about possibility; use could(n't) or be likely (Could it be that...?, Are you likely to...?); might in questions is rather formal. In negatives, may not / might not mean it is possible that something is not true, while can't / couldn't mean it is not possible that something is true (There can't be any milk left); can/could are also used with only, hardly, never. May well / might well / could well mean something is likely (Profits could well reach $100 million), but can well is not used for the future, only for present thoughts or feelings (I can well recall...). Conceivably and possibly also follow these modals (The President may conceivably call an election). Judge whether each student sentence chooses the right modal for the meaning and is well formed."
