      "instructionsEn": "Write 3-4 English sentences: speculate on what may have happened to a friend who is late, using **may/might/could have** + past participle (for example 'He might have got stuck in a traffic jam.'); then speculate on what might have happened to you by the end of next year using **I may/might/could (possibly/conceivably) have** + past participle, and use **I may/might/could well have** + past participle for the things that are particularly likely.",
      "ruleSummary": "May/might/could (not can) + have + past participle say it is possible that something happened in the past (She may/might/could have forgotten about the meeting). Might/could (not may or can) + have + past participle say something was possible in the past but did not in fact happen (The plan might/could easily have gone wrong, but it was a great success). Might (not may) + infinitive describes what was typically the case in the past (During the war, the police might arrest you for criticising the king); could + infinitive there means past ability or legal permission. May/might (not can) + have + past participle say that by some future time something will possibly have happened (By next Friday I may have completed the report), and may/might (not can) + be + -ing say something is possibly happening now or is a possible future arrangement (He may be working at home today). Could can replace may/might in these patterns to show more uncertainty, and the patterns combine for activities over a period until now (his sister might have been playing with it). May/might/could + well/conceivably/possibly + have + past participle say something is likely to have happened if circumstances had been different, or likely to have happened by a future time (By this time next week I could well have left for Washington); can well have is not used. Judge whether each student sentence uses the right modal and form for its time reference and meaning."
