      "instructionsEn": "Write 3-4 English sentences about your abilities: a general skill you had as a child (**I could** ...), something difficult you managed to do on a particular occasion (**I was able to** ...), and something you hope to be able to do in the future or after another modal (**I'll be able to** ..., **I might be able to** ...).",
      "ruleSummary": "Ability with can, could and be able to. Can('t)/cannot express present ability and could(n't) past ability (Anita could speak three languages before she was six); be able to can replace them (Helen can / is able to read well). For a general ability we prefer can (present) and could (past); for a specific, often difficult achievement we prefer be able to in the present and must use be able to, not could, in the past (Jenny was able to leave the hospital only six hours after the baby was born). With verbs of the senses (feel, hear, see, smell, taste) and of thinking (believe, decide, remember, understand) can/could are common even for specific occasions (She could feel the spray on her face). Be able to is not used for something happening as we speak, or before be + past participle (This furniture can be assembled by anyone). Be able to is needed after a to-infinitive, as an -ing form, in perfect tenses, or after another modal (lucky to be able to live; not being able to see you; have been able to match; may be able to move). Will be able to, not can, says something will be possible in the future, but can is used for a decision made now about the future (You can go home when you've finished). Negative past ability can be couldn't or wasn't able to. Judge whether each student sentence chooses can, could or be able to correctly and is well formed."
