              "kind": "text",
              "text": "**Must** has no other forms than the present tense (no past tense, no participles, etc.) and in past tense sentences which say that it was necessary to do something, we use **had to** instead:",
              "vi": "Must chỉ có dạng hiện tại (không có dạng quá khứ, không có phân từ, v.v.), nên trong câu ở quá khứ nói rằng đã cần phải làm việc gì, chúng ta dùng had to thay thế:"
