      "ruleSummary": "Must and have (got) to. Both say something is necessary (To get a cheap ticket, you must / have (got) to book in advance); for the future we can also use will have to; have got to is less formal and common in speech; need (to) is often similar. Have (got) to suggests an outside authority or circumstances make it necessary (I have to see the head teacher: she has called me), must that the speaker decides it (I must see the head teacher); have (got) to is preferred for a necessity characteristic of a person (Ann has got to have eight hours' sleep). Must, not have (got) to, is normally used to conclude that something is true (There must be about 2,000 people here), though informal speech allows have got to (You've got to be joking!); negative conclusions use can't or couldn't, not mustn't (That can't be right). Must has no past form: use had to for past necessity (He had to leave early) and must have + past participle for a conclusion about the past (You must have been upset). Have to, not have got to, is preferred with frequency adverbs (I often have to work at the weekend), in past simple questions and negatives (Did you have to...? We didn't have to wait), and in formal English; after contracted have/has/had use got (It's got to work, not It's to work). Judge whether each student sentence chooses must, have (got) to, had to, can't or must have correctly for its meaning and is well formed."
