      "instructionsEn": "Write a short English exchange of 4-5 lines, for example when you visit a friend's home: ask permission politely (**Could I...?**), press after being refused (**Couldn't I...?**), give or refuse permission (**You can / can't...**), offer food or drink (**Would you like...?**), and report something you were allowed to do in the past (**I was allowed to...**).",
      "ruleSummary": "Permission, offers and requests. To ask permission use can or could (could is more polite); can't or couldn't put extra pressure on the listener, for example after a refusal (Couldn't we stay a little longer?). To give or refuse permission prefer can / can't, not could / couldn't (No, you can't borrow the car tonight); may (not) and might are formal alternatives. To report permission use can for present or future and could for past (He said we can/could use the car); for general past permission use could or was/were allowed to (women were not allowed to / couldn't vote), but for one particular past action only was/were allowed to (Ken was allowed to come in, not could come in); in negatives couldn't and wasn't/weren't allowed to are both fine; with perfect tenses and infinitives use be allowed to (They have been allowed to keep the coins). Offers use can, could, shall or should (Shall/Should I phone for a taxi?), with could/should sounding less certain; shall/should also ask for confirmation or advice (Who shall I pass the message to?). Offers use Would you like..., not Will you like... (What would you like to drink? or What will you have to drink?, not What would you have / What will you like), and requests use I would ('d) like, not I'll like; should like with I/we is formal. Judge whether each student sentence uses the right modal for asking, giving, reporting permission, offering or requesting, and is well formed."
